#!/usr/bin/env bash
# scanner/build.sh — Build the sentrygrep-scanner Docker image.
#
# scanner/rules/ is GENERATED by this script from internal/rules/catalog/,
# not hand-maintained. Do not edit files in scanner/rules/ directly.
#
# Usage: Run from the repo root:
#   bash scanner/build.sh

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
RULES_SRC="$REPO_ROOT/internal/rules/catalog"
RULES_DST="$REPO_ROOT/scanner/rules"

# 1. Remove and recreate scanner/rules/
rm -rf "$RULES_DST"
mkdir -p "$RULES_DST"

# 2. Copy each catalog rule.yaml, renamed to the catalog directory's name.
#    e.g. internal/rules/catalog/cwe-78-cmdinject/rule.yaml -> scanner/rules/cwe-78-cmdinject.yaml
found=0
for dir in "$RULES_SRC"/*; do
    [ -d "$dir" ] || continue
    dir_name="$(basename "$dir")"
    if [ ! -f "$dir/rule.yaml" ]; then
        echo "ERROR: Missing rule.yaml in $dir" >&2
        exit 1
    fi
    if [ ! -f "$dir/meta.yaml" ]; then
        echo "ERROR: Missing meta.yaml in $dir" >&2
        exit 1
    fi
    mkdir -p "$RULES_DST/$dir_name"
    cp "$dir/rule.yaml" "$dir/meta.yaml" "$RULES_DST/$dir_name/"
    echo "  copied: $dir_name"
    found=$((found + 1))
done

if [ "$found" -eq 0 ]; then
    echo "WARNING: No rule.yaml files found in $RULES_SRC/*/rule.yaml" >&2
    exit 1
fi
echo "Copied $found rule(s) into scanner/rules/"

# 3. Build Docker image
docker build -t sentrygrep-scanner "$REPO_ROOT/scanner/"
